<?php $title='Utilisateurs';require '../includes/header.php';if(user()['role']!=='admin')exit('Accès refusé');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['delete']))$pdo->prepare("DELETE FROM users WHERE id=? AND id<>?")->execute([(int)$_POST['id'],user()['id']]);else $pdo->prepare("INSERT INTO users(nom,email,password,role) VALUES(?,?,?,?)")->execute([$_POST['nom'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);header('Location:users.php');exit;}$rows=$pdo->query("SELECT id,nom,email,role,actif,created_at FROM users ORDER BY id DESC")->fetchAll();?><h1>Utilisateurs</h1><form method="post" class="card"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><div class="field"><label>Nom</label><input name="nom" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Mot de passe</label><input name="password" type="password" required></div><div class="field"><label>Rôle</label><select name="role"><option>agent</option><option>superviseur</option><option>admin</option></select></div></div><br><button class="btn">Créer</button></form><br><div class="table-wrap"><table class="table"><tr><th>Nom</th><th>Email</th><th>Rôle</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nom'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?php if($r['id']!=user()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" name="delete" value="1">Supprimer</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php require '../includes/footer.php';?>